<script setup lang="ts">
import { computed, ref } from 'vue'
import CompositionEditor from '../components/CompositionEditor.vue'
import WorkbenchLayout from '../components/WorkbenchLayout.vue'
import SpectrumChart from '../components/SpectrumChart.vue'
import EmptyStateArt from '../components/EmptyStateArt.vue'
import TaskActivity from '../components/TaskActivity.vue'
import { advanced, activeTask, runReal } from '../lib/workbench'
import { numeric, validateComposition, validateParams, errorOf, format } from '../lib/model'
import { apiParams, apiComposition } from '../lib/backend'
const running=activeTask('advanced'), submitError=ref(''),compositionError=ref('')
const fields=[{key:'te',label:'名义 Te / eV'},{key:'ne',label:'名义 Ne / cm⁻³'},{key:'resolution',label:'仪器 R'},{key:'low',label:'下界 / nm'},{key:'high',label:'上界 / nm'},{key:'step',label:'输出步长 / nm'},{key:'charge',label:'最大发射电荷（0–2）'}] as const
function prepare() {
  const p=validateParams({...advanced.params,mode:'local',flux:'photon',broaden:true,temperatureMode:'manual',temperature:'0',gaussian:'0',lorentz:'0',resample:false})
  if((p.high-p.low)/((p.high+p.low)/2)>.05)throw Error('窄带仪器近似要求波段跨度≤中心波长的5%，请缩小范围')
  if(compositionError.value)throw Error(compositionError.value)
  const comp=validateComposition(advanced.composition)
  const unsupported=comp.filter(e=>e.pct>0 && !['Mg','Ca','Zn'].includes(e.symbol)).map(e=>e.symbol)
  if(unsupported.length)throw Error(`${unsupported.join('、')} 缺少论文 Stark/三态原子数据；默认支持 Mg、Ca、Zn`)
  const responses=Object.fromEntries(comp.map(e=>[e.symbol,advanced.matrix ? numeric(advanced.responses[e.symbol]??'1',`${e.symbol} 响应`,0,1e6) : 1]))
  if(advanced.matrix && !comp.some(e=>e.pct>0 && responses[e.symbol]!>0))throw Error('有效元素响应不能全为零')
  return {params:apiParams(p),composition:apiComposition(comp),advanced:{self_absorption:advanced.selfAbsorption,instrument_broadening:advanced.instrumentBroadening,matrix:advanced.matrix,column_cm2:numeric(advanced.column,'总原子/离子柱密度',0,1e24),path_length_m:numeric(advanced.pathLength,'光程',1e-12,1e6),responses,te_factor:advanced.matrix ? numeric(advanced.teFactor,'Te倍率',1e-4,1e4) : 1,ne_factor:advanced.matrix ? numeric(advanced.neFactor,'Ne倍率',1e-4,1e4) : 1}}
}
const inputError=computed(()=>errorOf(prepare))
const diagnostics=computed(()=>advanced.result?.source.origin?.diagnostics as Record<string,number>|undefined)
const matrixResult=computed(()=>advanced.result?.source.origin?.matrix as Record<string,number>|undefined)
const paperResult=computed(()=>advanced.result?.source.origin?.model_version==='paper-eq7-stark-sa-1')
async function run(){try{submitError.value='';await runReal('advanced','高级本地真实计算',prepare())}catch(e){submitError.value=String(e)}}
</script>
<template><WorkbenchLayout kind="advanced"><template #controls="{disabled}"><fieldset class="control-fieldset" :disabled="disabled"><div class="panel-heading"><h2>高级单次参数</h2><span class="badge neutral">论文逐线 Stark</span></div><div class="row2"><label v-for="field in fields" :key="field.key" class="field">{{ field.label }}<input :id="`advanced-${field.key}`" v-model="advanced.params[field.key]" type="text" inputmode="decimal" /></label></div><div class="row2"><label class="field">总原子/离子柱密度 / cm⁻²<input id="advanced-column" v-model="advanced.column" type="text" /></label><label class="field">光程 L / m<input id="advanced-path-length" v-model="advanced.pathLength" type="text" /></label></div><p class="hint">总数密度 N = 柱密度 / (100 × L)，单位 cm⁻³；基体产额倍率再作用于 N。N 与电子密度 Ne 分别指定。</p><div class="divider" /><label class="switch"><input v-model="advanced.selfAbsorption" type="checkbox" aria-label="高级自吸收" /><span class="switch-track" />逐线自吸收</label><label class="switch"><input v-model="advanced.instrumentBroadening" type="checkbox" aria-label="高级仪器Gaussian卷积" /><span class="switch-track" />仪器 Gaussian 卷积</label><p class="hint">吸收使用论文 Stark 参数并随 Ne 缩放，逐线更新峰高与线宽后叠加。R 仅控制吸收后的仪器响应。旧热、附加 Gaussian/Lorentz 草稿字段不参与本模型。</p><div class="divider" /><label class="switch"><input v-model="advanced.matrix" type="checkbox" aria-label="参数化基体效应" /><span class="switch-track" />参数化基体效应</label><div class="row2"><label class="field">Te 修正倍率<input v-model="advanced.teFactor" :disabled="!advanced.matrix" type="text" /></label><label class="field">Ne 修正倍率<input v-model="advanced.neFactor" :disabled="!advanced.matrix" type="text" /></label></div></fieldset><div class="divider" /><CompositionEditor v-model="advanced.composition" scope="advanced" :disabled="disabled" @issue="compositionError=$event" /><fieldset class="control-fieldset" :disabled="disabled || !advanced.matrix"><label v-for="row in advanced.composition" :key="row.id" class="field">{{ row.symbol }} 元素响应（默认1）<input :value="advanced.responses[row.symbol]??'1'" type="text" @input="advanced.responses[row.symbol]=($event.target as HTMLInputElement).value" /></label></fieldset><p class="hint">未标定参数模型，可后续用实验校准；不是普适材料预测。</p><button class="btn primary full" :disabled="!!running || !!inputError" @click="run">运行高级模拟</button></template><section class="panel activity-panel"><h2>论文 Eq.7 · Stark 逐线自吸收</h2><p class="hint">默认使用论文 Table 1 的 Mg、Ca、Zn 共31条谱线与 NIST I/II/III 能级计算三态 Saha 布居；谱线数据覆盖 I/II，缺必要 Stark/原子数据的元素会明确拒绝。逐线计算 τ、SA 和吸收展宽，不预测自反转、时空梯度或连续吸收。相对波段限5%，超出数值资源上限会明确拒绝。</p></section><SpectrumChart v-if="advanced.result" :spectrum="advanced.result" label="高级三谱对照" /><section v-else class="panel empty-state"><EmptyStateArt /><h3>尚无高级结果</h3><p>运行后显示名义薄谱、基体薄谱及自吸收修正谱。</p></section><section v-if="diagnostics" class="panel activity-panel"><h2>已完成结果诊断</h2><p>{{ paperResult ? '逐线中心最大 τ' : '已保存模型最大 τ' }} {{ format(diagnostics.tau_max!) }} · {{ paperResult ? '最小 SA' : '最小 β' }} {{ format(diagnostics.beta_min!) }} · 谱线 {{ diagnostics.line_count }}</p><p v-if="matrixResult">有效 Te {{ format(matrixResult.effective_Te_eV!) }} eV · Ne {{ format(matrixResult.effective_Ne_cm3!) }} cm⁻³<span v-if="matrixResult.effective_number_density_cm3!==undefined"> · N {{ format(matrixResult.effective_number_density_cm3) }} cm⁻³</span> · 产额倍率 {{ format(matrixResult.yield_scale!) }}</p><p v-if="paperResult" class="hint">三个谱共用显示尺度与相同仪器响应，采用 photon 强度。CSV/JSON携带三谱对照；JSON 的 opacity 是逐线中心 τ/SA 诊断，未表示连续总光学厚度。PNG保留颜色图例。</p><p v-else class="hint">这是已保存的旧高级模型结果；来源、参数和诊断按原记录保留。新计算使用上方论文模型。</p></section><TaskActivity kind="advanced" :error="inputError || submitError" /></WorkbenchLayout></template>
